<?php $movement=$data['movement']??['rows'=>[],'summary'=>[],'days'=>0]; $activeShop=(int)($data['active_shop_id']??0); $rows=$movement['rows']??[]; ?>
<section id="product-movement-page" aria-labelledby="product-movement-title">
  <div class="mb-5 flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
    <div><h1 id="product-movement-title" class="text-2xl font-bold">Pergerakan produk</h1><p class="mt-1 text-sm text-base-content/70">Laju penjualan dan posisi stok untuk <?= (int)($movement['days']??0); ?> hari terakhir.</p></div>
    <div class="flex flex-wrap gap-2"><a class="btn btn-ghost btn-sm" href="<?= burl; ?>/panel/products?shop_id=<?= $activeShop; ?>">Daftar produk</a><a class="btn btn-primary btn-sm" href="<?= burl; ?>/panel/products?shop_id=<?= $activeShop; ?>&view=movement#bundling-draft">Pilih kandidat bundling</a></div>
  </div>
  <div class="mb-5 grid grid-cols-2 gap-3 sm:grid-cols-5">
    <?php foreach ([['fast','Fast moving','trending_up'],['slow','Slow moving','hourglass_top'],['dead','Dead stock','inventory_2'],['empty','Stok habis','remove_shopping_cart'] ] as [$key,$label,$icon]): ?><div class="rounded-xl border border-base-300 bg-base-100 p-3"><span class="material-symbols-outlined text-base-content/70" aria-hidden="true"><?= $icon; ?></span><strong class="mt-2 block text-xl"><?= (int)($movement['summary'][$key]??0); ?></strong><span class="text-xs text-base-content/70"><?= $label; ?></span></div><?php endforeach; ?>
  </div>
  <div class="mb-5 rounded-xl border border-base-300 bg-base-100 p-4"><p class="text-sm"><strong>Cara membaca:</strong> Fast moving memakai laju jual tinggi dibanding produk lain di toko. Slow moving masih terjual dengan laju lebih rendah. Dead stock memiliki stok tetapi tidak terjual selama periode ini. Stok habis dipisahkan dari dead stock.</p></div>
  <div class="overflow-hidden rounded-xl border border-base-300 bg-base-100">
    <div class="flex flex-wrap items-center justify-between gap-3 border-b border-base-300 p-4"><div><h2 class="font-bold">Rekap penjualan dan stok</h2><p class="text-xs text-base-content/70">Periode <?= htmlspecialchars($movement['start']??'',ENT_QUOTES); ?> sampai <?= htmlspecialchars($movement['end']??'',ENT_QUOTES); ?>. Data berasal dari pesanan selesai.</p></div><span class="text-xs text-base-content/70">Toko: <?= htmlspecialchars($data['movement_shop_name']??'Toko',ENT_QUOTES); ?></span></div>
    <?php if (!$rows): ?><div class="p-10 text-center text-sm text-base-content/70">Belum ada data produk untuk dianalisis.</div><?php else: ?><div class="overflow-x-auto"><table class="table w-full"><thead><tr><th>Pilih</th><th>Produk</th><th>Status</th><th class="text-right">Terjual</th><th class="text-right">Rata-rata/hari</th><th class="text-right">Stok</th><th class="text-right">Perkiraan hari</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?php if (in_array($row['movement_key'],['slow','dead'],true) && (int)$row['total_stock']>0): ?><label class="flex min-h-11 items-center"><input type="checkbox" class="checkbox" data-bundle-product data-product-id="<?= (int)$row['id']; ?>" data-product-name="<?= htmlspecialchars($row['name'],ENT_QUOTES); ?>" data-movement-label="<?= htmlspecialchars($row['movement_label'],ENT_QUOTES); ?>" aria-label="Pilih <?= htmlspecialchars($row['name'],ENT_QUOTES); ?> untuk draft bundling"></label><?php else: ?><span class="text-xs text-base-content/50">-</span><?php endif; ?></td><td><div class="flex min-w-[220px] items-center gap-3"><div class="h-10 w-10 shrink-0 overflow-hidden rounded border border-base-300 bg-base-200"><?php if (!empty($row['cover_image'])): ?><img src="https://cf.shopee.co.id/file/<?= htmlspecialchars($row['cover_image'],ENT_QUOTES); ?>" alt="<?= htmlspecialchars('Produk: '.$row['name'],ENT_QUOTES); ?>" class="h-full w-full object-cover" loading="lazy"><?php endif; ?></div><div class="min-w-0"><strong class="block break-words"><?= htmlspecialchars($row['name'],ENT_QUOTES); ?></strong><span class="text-xs text-base-content/60"><?= htmlspecialchars($row['parent_sku']?:'SKU tidak tersedia',ENT_QUOTES); ?></span></div></div></td><td><span class="badge" data-movement="<?= htmlspecialchars($row['movement_key'],ENT_QUOTES); ?>"><?= htmlspecialchars($row['movement_label'],ENT_QUOTES); ?></span></td><td class="text-right"><?= number_format((int)$row['units_sold'],0,',','.'); ?></td><td class="text-right"><?= number_format((float)$row['daily_rate'],2,',','.'); ?></td><td class="text-right"><?= number_format((int)$row['total_stock'],0,',','.'); ?></td><td class="text-right"><?= $row['stock_days']===null?'Belum ada laju jual':number_format((float)$row['stock_days'],1,',','.').' hari'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
  </div>
  <section id="bundling-draft" class="mt-5 rounded-xl border border-base-300 bg-base-100 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="font-bold">Draft bundling</h2><p class="mt-1 text-sm text-base-content/70">Pilih produk slow moving atau dead stock. Draft ini hanya tersimpan di halaman dan tidak mengubah listing.</p></div><button id="bundle-clear" type="button" class="btn btn-ghost btn-sm" disabled>Hapus pilihan</button></div><div id="bundle-selection" class="mt-3 text-sm text-base-content/70">Belum ada produk yang dipilih.</div></section>
</section>
<script>
(() => { const boxes=[...document.querySelectorAll('[data-bundle-product]')], list=document.getElementById('bundle-selection'), clear=document.getElementById('bundle-clear'); if(!list||!clear)return; const render=()=>{const selected=boxes.filter(b=>b.checked); clear.disabled=!selected.length; list.innerHTML=selected.length?'<ul class="grid gap-2 sm:grid-cols-2">'+selected.map(b=>'<li class="rounded-lg border border-base-300 px-3 py-2"><strong>'+b.dataset.productName+'</strong><span class="block text-xs text-base-content/60">'+b.dataset.movementLabel+'</span></li>').join('')+'</ul>':'Belum ada produk yang dipilih.';}; boxes.forEach(b=>b.addEventListener('change',render)); clear.addEventListener('click',()=>{boxes.forEach(b=>b.checked=false);render();}); })();
</script>
